  ui_story_5052_50520101_26_dialog_content = "Oh, certo! Este é o livro que <color=#FFB400>Victoria</color> está sempre carregando!",
  ui_story_5052_50520101_27_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5052_50520101_28_dialog_content = "As páginas estão virando sozinhas. Deixe-me ver o que há nas páginas.",
  ui_story_5052_50520101_29_dialog_content = "Hmmm, algumas notas foram escritas para mim.",
  ui_story_5052_50520101_30_dialog_content = "\"Navegador, você já deve ter tropeçado nesta mensagem.\"",
  ui_story_5052_50520101_31_dialog_content = "\"Você está prestes a enfrentar uma situação única <color=#FFB400>julgamento</color>, como você nunca experimentou antes.\"",
  ui_story_5052_50520101_32_dialog_content = "\"Mas fique tranquilo, o <color=#FFB400>Tomo Preto</color> mostra bondade para com todos os seus leitores...\"",
  ui_story_5052_50520101_33_dialog_content = "\"Você deve aceitar a mudança se quiser ter sucesso, Navegador.\"",
  ui_story_5052_50520101_34_dialog_content = "\"Este novo julgamento é desafiador, mas bastante agradável. Mesmo eu não consegui chegar a sua gloriosa conclusão.\"",
  ui_story_5052_50520101_35_dialog_content = "\"Devemos enfrentar cada um de seus testes com a maior devoção e submissão...\"",
  ui_story_5052_50520101_36_dialog_content = "\"Não deixe esses caras te confundirem, PlayerName. Este julgamento não é tão complicado quanto eles fazem parecer.\"",
  ui_story_5052_50520101_37_dialog_content = "\"Isso nada mais é do que um capricho passageiro do destino, que já foi determinado há muito tempo.\"",
  ui_story_5052_50520101_38_dialog_content = "\"Apenas lembra-te...\"",
  ui_story_5052_50520101_39_dialog_content = "\"Queime Depois de Ler.\"",
  ui_story_5052_50520101_40_dialog_content = "\"Huh? Por que eu tenho que deixar uma mensagem para ele também?",
  ui_story_5052_50520101_41_dialog_content = "\"Apenas escreva algo para mim, ok? Não é como PlayerName vai realmente lê-lo ou qualquer coisa.\"",
  ui_story_5052_50520101_42_dialog_content = "\"Vocês são ótimos em inventar coisas enigmáticas que ninguém entende. Basta ir com algo assim!\"",
  ui_story_5052_50520101_43_dialog_content = "\"Além disso, é hora do meu chá da tarde. Tchau!\"",
  ui_story_5052_50520101_44_dialog_content = "...",
  ui_story_5052_50520101_45_option_content = "Eu entendi tudo completamente.",
  ui_story_5052_50520101_46_dialog_content = "Suas palavras são tão vagas e confusas como sempre, mas acho que entendi a essência das coisas.",
  ui_story_5052_50520101_47_dialog_content = "Estou aqui para passar por algum tipo de <color=#FFB400>julgamento</color>, certo?",
  ui_story_5052_50520101_48_dialog_content = "<color=#e8d9bb>As páginas do livro começam a virar mais uma vez. De repente, as palavras começam a aparecer em uma página em branco...</color>",
  ui_story_5052_50520101_49_dialog_content = "\"Correto.\"",
  ui_story_5052_50520101_50_option_content = "Isso com certeza foi um monte de bobagens.",
  ui_story_5052_50520101_51_dialog_content = "Apesar de todas as suas palavras inúteis, eles podem muito bem não ter dito nada.",
  ui_story_5052_50520101_52_dialog_content = "De qualquer forma, que tipo de <color=#FFB400>julgamento</color> eles estão falando? O que eles querem dizer com \"como nunca antes experimentei\"?",
  ui_story_5052_50520101_53_dialog_content = "<color=#e8d9bb>As páginas do livro começam a virar mais uma vez. De repente, as palavras começam a aparecer em uma página em branco...</color>",
  ui_story_5052_50520101_54_dialog_content = "\"Isso significa que é extremamente diferente.\"",
  ui_story_5052_50520101_55_dialog_content = "?!",
  ui_story_5052_50520101_56_dialog_content = "I-Essa coisa está escrevendo para mim?!",
  ui_story_5052_50520101_57_dialog_content = "\"Olá, PlayerName.\"",
  ui_story_5052_50520101_58_dialog_content = "Olá?",
  ui_story_5052_50520101_59_dialog_content = "Espere, este livro pode realmente me ouvir, ou eu tenho que escrever minhas respostas nele?",
  ui_story_5052_50520101_60_dialog_content = "\"Eu posso ouvir você.\"",
  ui_story_5052_50520101_61_dialog_content = "Isto é tão estranho...",
  ui_story_5052_50520101_62_option_content = "O que tá acontecendo aqui?",
  ui_story_5052_50520101_63_dialog_content = "\"Eu estou te esperando há muito tempo.\"",
  ui_story_5052_50520101_64_dialog_content = "\"Os discípulos da Verdade prepararam uma série de <color=#FFB400>ensaios</color> para você superar. Eu confio que você está pronto?\"",
  ui_story_5052_50520101_65_option_content = "Qual o seu nome?",
  ui_story_5052_50520101_66_dialog_content = "\"Não tenho nome, mas todas as coisas são feitas em meu nome.\"",
  ui_story_5052_50520101_67_dialog_content = "\"Pois sem um nome, somos todos iguais.\"",
  ui_story_5052_50520101_68_dialog_content = "Então, qual é o seu propósito aqui?",
  ui_story_5052_50520101_69_dialog_content = "\"Neste exato momento, meu propósito é compartilhar uma experiência única <color=#FFB400>julgamento</color> com você.\"",
  ui_story_5052_50520101_70_option_content = "(Tente usar habilidades psíquicas)",
  ui_story_5052_50520101_71_dialog_content = "\"Não tente sondar as profundezas da minha consciência, celestita. Sou muito mais do que pareço ser.\"",
  ui_story_5052_50520101_72_dialog_content = "(Droga, percebeu!)",
  ui_story_5052_50520101_73_dialog_content = "\"Nem todos os livros são destinados aos olhos mortais. Você entende?\"",
  ui_story_5052_50520101_74_dialog_content = "(Então por que você tomaria a forma de um livro...?)",
  ui_story_5052_50520101_75_dialog_content = "\"Concentre-se no iminente <color=#FFB400>julgamento</color>, celestita. Eu preparei especialmente para você.\"",
  ui_story_5052_50520101_76_dialog_content = "Sim, eu imaginei isso.",
  ui_story_5052_50520101_77_dialog_content = "May Eu pergunto o que este julgamento implica? Eu realmente não me preparei para nada, para ser honesto.",
  ui_story_5052_50520101_78_dialog_content = "\"Não requer nenhuma preparação especial. Por enquanto, pegue-me e passe pela porta do outro lado da sala.\"",
  ui_story_5052_50520101_79_dialog_content = "\"Seu desafio espera por você lá.\"",
  ui_story_5052_50520101_80_dialog_content = "Está bem então. Uh... M-May Eu te pego agora?",
  ui_story_5052_50520101_81_dialog_content = "(Urgh, essa coisa é mais pesada do que parece.)",
  ui_story_5052_50520101_82_dialog_content = "(Não Victoria se cansa de carregá-lo o tempo todo?)",
  ui_story_5052_50520101_83_dialog_content = "\"Abra a porta. Vou explicar o próximo passo do seu julgamento em breve.\"",
  ui_story_5052_50520102_1_dialog_content = "\"Bom trabalho, PlayerName.\"",
  ui_story_5052_50520102_2_dialog_content = "\"Sua adaptabilidade superou minhas expectativas. Como você se sente agora?\"",
  ui_story_5052_50520102_3_dialog_content = "Isso foi muito diferente de qualquer uma das minhas batalhas anteriores.",
  ui_story_5052_50520102_4_option_content = "Eu me sinto ótimo!",
  ui_story_5052_50520102_5_dialog_content = "Não precisei pensar muito. Tudo o que eu tinha que fazer era forçar meu caminho através dele.",
  ui_story_5052_50520102_6_dialog_content = "As restrições de movimento também foram muito mais relaxadas! Que projeto incrível!",
  ui_story_5052_50520102_7_dialog_content = "Então, por que exatamente você preparou este desafio para mim?",
  ui_story_5052_50520102_8_option_content = "Não sei...",
  ui_story_5052_50520102_9_dialog_content = "Sempre parece tão irreal quando posso lutar sem a maioria das restrições usuais de combate.",
  ui_story_5052_50520102_10_dialog_content = "Além disso, a distribuição do Lumina foi claramente adulterada, o que tornou a luta ainda mais irreal.",
  ui_story_5052_50520102_11_dialog_content = "Então, por que exatamente você preparou este julgamento para mim?",
  ui_story_5052_50520102_12_option_content = "Entediado fora de minha mente.",
  ui_story_5052_50520102_13_dialog_content = "Parecia muito fabricado, como se tivesse sido projetado para me dar esse tipo exato de experiência de combate.",
  ui_story_5052_50520102_14_dialog_content = "Não foi um grande desafio. Na verdade, a falta de restrições me fez sentir que a vitória estava garantida.",
  ui_story_5052_50520102_15_dialog_content = "Para ser sincero, prefiro batalhas mais realistas e desafiadoras a vitórias fáceis.",
  ui_story_5052_50520102_16_dialog_content = "Então, qual era o sentido de passar por todo o trabalho de planejar esse teste?",
  ui_story_5052_50520102_17_dialog_content = "\"Sua percepção está mais aguçada do que nunca, Celestita.\"",
  ui_story_5052_50520102_18_dialog_content = "Er, b-bem, eu passei por uma tonelada de batalhas, sabe? É natural para mim ter alguma percepção sobre eles.",
  ui_story_5052_50520102_19_dialog_content = "\"Então, estou ansioso para ver seu desempenho no próximo julgamento ainda mais.\"",
  ui_story_5052_50520102_20_dialog_content = "Huh? Tem mais?",
  ui_story_5052_50520102_21_dialog_content = "\"Claro. Você está começando a se sentir cansado, por acaso?\"",
  ui_story_5052_50520102_22_option_content = "Não, estou ansioso para ir!",
  ui_story_5052_50520102_23_dialog_content = "\"Bom. Então vamos continuar.\"",
  ui_story_5052_50520102_24_dialog_content = "\"Estou ansioso para ver o quão bem você se sai, Celestita...\"",
  ui_story_5052_50520102_25_option_content = "Talvez eu esteja um pouco cansada...",
  ui_story_5052_50520102_26_dialog_content = "Acho que preciso de alguns minutos para descansar. Afinal, tudo isso foi tão repentino.",
  ui_story_5052_50520102_27_dialog_content = "Onde está a saída?",
  ui_story_5052_50520102_28_dialog_content = "\"Sair? Você honestamente acreditou que poderia sair antes de completar cada etapa do seu julgamento?",
  ui_story_5052_50520102_29_dialog_content = "Hã?",
  ui_story_5052_50520102_30_dialog_content = "\"A oportunidade de ver um celestita em batalha é extremamente rara. Não tenho intenção de deixá-lo ir tão facilmente.\"",
  ui_story_5052_50520102_31_dialog_content = "\"Agora vamos continuar.\"",
  ui_story_5052_50520102_32_dialog_content = "(Por ser um livro, com certeza tem uma atitude podre...)",
  ui_story_5052_50520502_1_dialog_content = "\"Parabéns, celestita. Acima estão os resultados deste teste.\"",
  ui_story_5052_50520502_2_dialog_content = "\"Você tem algum pensamento que gostaria de compartilhar?\"",
  ui_story_5052_50520502_3_dialog_content = "Bem, há algumas coisas que estão me incomodando há algum tempo.",
  ui_story_5052_50520502_4_dialog_content = "Primeiro, quem exatamente planejou tudo isso? Foi você, ou foi Victoria?",
  ui_story_5052_50520502_5_dialog_content = "E onde estão os outros membros da Verdadeira Ordem? Desde que cheguei aqui, não vi nenhum deles!",
  ui_story_5052_50520502_6_dialog_content = "\"Antes de responder, devo fazer mais uma pergunta...\"",
  ui_story_5052_50520502_7_dialog_content = "\"Você sabe a razão pela qual a Verdadeira Ordem existe?\"",
  ui_story_5052_50520502_8_option_content = "Para buscar a Verdade.",
  ui_story_5052_50520502_9_dialog_content = "Buscar a Verdade e qualquer coisa relacionada a ela, algo assim.",
  ui_story_5052_50520502_10_dialog_content = "Não tenho certeza, agora que penso nisso. Isso tem algo a ver com o meu julgamento?",
  ui_story_5052_50520502_11_dialog_content = "\"Sim.\"",
  ui_story_5052_50520502_12_option_content = "Para viajar pelo mundo.",
  ui_story_5052_50520502_13_dialog_content = "Os membros da Verdadeira Ordem tendem a aparecer em todo o mundo, especialmente em lugares onde eu menos esperaria vê-los.",
  ui_story_5052_50520502_14_dialog_content = "Portos, vilas, praias e vales...",
  ui_story_5052_50520502_15_dialog_content = "\"Como servos e buscadores da Verdade, é seu dever sagrado procurá-la até mesmo nos locais mais remotos.\"",
  ui_story_5052_50520502_16_option_content = "Para falar um monte de bobagens.",
  ui_story_5052_50520502_17_dialog_content = "Mesmo depois de conhecer tantas pessoas na Verdadeira Ordem por tanto tempo, ainda não tenho ideia do que vocês estão procurando.",
  ui_story_5052_50520502_18_dialog_content = "Na maioria das vezes, seus sermões prolixos me deixam mais confuso do que antes de ouvi-los.",
  ui_story_5052_50520502_19_dialog_content = "E isso vale em dobro para Faust! Aquele cara pode falar por horas sem dizer nada nem remotamente importante!",
  ui_story_5052_50520502_20_dialog_content = "\"Eu concordo. Até eu acho difícil de suportar às vezes.\"",
  ui_story_5052_50520502_21_dialog_content = "\"Permita-me oferecer uma explicação mais simples...\"",
  ui_story_5052_50520502_22_dialog_content = "\"Nosso propósito é investigar as origens deste mundo.\"",
  ui_story_5052_50520502_23_dialog_content = "As origens deste mundo?",
  ui_story_5052_50520502_24_dialog_content = "\"Correto. Procuramos entender de onde você veio e onde está seu destino.\"",
  ui_story_5052_50520502_25_dialog_content = "\"Para descobrir o ser que lhe concedeu seus poderes e confirmar se ele continua ou não cuidando de todos nós.\"",
  ui_story_5052_50520502_26_dialog_content = "\"Você não está curioso para saber também?",
  ui_story_5052_50520502_27_dialog_content = "Espere, por que você está falando de mim, de repente?",
  ui_story_5052_50520502_28_dialog_content = "\"...\"",
  ui_story_5052_50520502_29_dialog_content = "\"Isso não é importante agora, celestita.\"",
  ui_story_5052_50520502_30_dialog_content = "\"De qualquer forma, este julgamento foi apenas nossa primeira tentativa de descobrir esses segredos.\"",
  ui_story_5052_50520502_31_dialog_content = "\"Pode não estar claro para você agora, mas a Verdade tem um plano para todos nós.\"",
  ui_story_5052_50520502_32_dialog_content = "Que plano? Você não pode ser um pouco mais específico?",
  ui_story_5052_50520502_33_dialog_content = "\"...\"",
  ui_story_5052_50520502_34_dialog_content = "\"Nos veremos mais uma vez em um futuro muito próximo, celestita.\"",
  ui_story_5052_50520502_35_dialog_content = "\"Quando esse dia chegar, espero que você esteja pronto para aceitar seu novo destino.\"",
  ui_story_5052_50520502_36_dialog_content = "Meu novo destino? Afinal, o que isso quer dizer?!",
  ui_story_5052_50520502_37_dialog_content = "\"...\"",
  ui_story_5052_50520502_38_dialog_content = "\"A saída é ali.\"",
  ui_story_5052_50520502_39_dialog_content = "Então eu posso finalmente sair agora?",
  ui_story_5052_50520502_40_dialog_content = "\"...\"",
  ui_story_5052_50520502_41_dialog_content = "\"...\"",
  ui_story_5052_50520502_42_dialog_content = "(O livro não está mais respondendo.)",
  ui_story_5052_50520502_43_dialog_content = "(No final das contas, fazia tão pouco sentido quanto o resto dos membros da Verdadeira Ordem...)"
}
